<?php elseif($page==='books'):$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$st=db()->prepare('SELECT b.*,c.name category FROM books b JOIN categories c ON c.id=b.category_id WHERE (b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ?) AND (?=0 OR c.id=?) ORDER BY b.id DESC');$like="%$q%";$st->execute([$like,$like,$like,$cat,$cat]);$books=$st->fetchAll();?><div class="toolbar"><form class="d-flex gap-2 book-search"><input type="hidden" name="page" value="books"><input class="form-control" name="q" placeholder="Cari judul, penulis, ISBN" value="<?=e($q)?>"><select class="form-select" name="category"><option value="0">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select><button class="btn btn-outline-primary">Cari</button></form><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#bookModal">+ Tambah Buku</button></div><div class="row g-3 book-grid"><?php foreach($books as $b):$cover=$b['cover']?:'assets/images/cover-default.svg';?><div class="col-6 col-lg-4 col-xxl-3"><article class="book-card"><a href="?page=book&id=<?=$b['id']?>"><img class="book-cover" src="<?=e($cover)?>" alt="Sampul <?=e($b['title'])?>"></a><div class="book-card-body"><span class="book-category"><?=e($b['category'])?></span><h3><a href="?page=book&id=<?=$b['id']?>"><?=e($b['title'])?></a></h3><p class="book-author"><?=e($b['author'])?></p><div class="stock-line"><span>Stok tersedia</span><strong><?=$b['stock']?></strong></div><div class="book-actions"><a class="btn btn-sm btn-outline-secondary" href="?page=book&id=<?=$b['id']?>">Detail</a><a class="btn btn-sm btn-outline-primary" href="?page=editbook&id=<?=$b['id']?>">Edit</a><form method="post" action="?page=action" onsubmit="return confirm('Hapus buku ini?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="book_delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></div></div></article></div><?php endforeach?><?php if(!$books):?><div class="col-12"><div class="panel text-center text-secondary py-5">Buku tidak ditemukan.</div></div><?php endif?></div><?php render_book_modal($cats);
